$ErrorActionPreference='Stop';$root=$PSScriptRoot;$qpf=[double][Diagnostics.Stopwatch]::Frequency;$names=@('CPU_CLK_UNHALTED.REF_TSC','CPU_CLK_UNHALTED.THREAD','INST_RETIRED.ANY','OFFCORE_REQUESTS.L3_MISS_DEMAND_DATA_RD','OFFCORE_REQUESTS.DEMAND_DATA_RD')
function Num($s){$s=$s.Trim();if($s -notmatch '^\d[\d,]*(?:\.\d+)?$'){return [double]::NaN};[double]::Parse($s.Replace(',',''),[Globalization.CultureInfo]::InvariantCulture)}
$result=[Collections.Generic.List[object]]::new();$caps=@('capture_diag_weights2_r5','capture_diag_nonweights2_r5','capture_diag_idle2_r5')
foreach($cap in $caps){$dir=Join-Path $root $cap;$stdout=Get-Content (Join-Path $dir 'control.stdout.txt') -Raw;$mode=[regex]::Match($stdout,'CONTROL=(\w+)').Groups[1].Value;$m=[regex]::Match($stdout,'qpc_pad_start=(\d+) qpc_start=(\d+) qpc_end=(\d+) qpc_pad_end=(\d+)');if(!$m.Success){throw "control QPC marks missing: $cap"};$pa=[double]$m.Groups[1].Value/$qpf;$a=[double]$m.Groups[2].Value/$qpf;$b=[double]$m.Groups[3].Value/$qpf;$pb=[double]$m.Groups[4].Value/$qpf
 $raw=Get-Content (Join-Path $dir 'emon_stdout.txt') -Raw;$map=@(Import-Csv (Join-Path $dir 'clock_map.csv'));$x=[double[]]@($map|%{[double]$_.filetime_100ns});$y=[double[]]@($map|%{([double]$_.qpc_pre+[double]$_.qpc_post)/2});$xm=($x|Measure-Object -Average).Average;$ym=($y|Measure-Object -Average).Average;$nn=0.;$dd=0.;for($i=0;$i-lt$x.Count;$i++){$nn+=($x[$i]-$xm)*($y[$i]-$ym);$dd+=($x[$i]-$xm)*($x[$i]-$xm)};$slope=$nn/$dd;$inter=$ym-$slope*$xm
 $records=[Collections.Generic.List[object]]::new();foreach($chunk in [regex]::Split($raw,'(?m)^==========\s*$')){$tm=[regex]::Match($chunk,'(?m)^(\d{1,2}/\d{1,2}/\d{4}\s+\d{2}:\d{2}:\d{2}\.\d{3})\s*$');if(!$tm.Success){continue};$dt=[datetime]::ParseExact($tm.Groups[1].Value,'M/d/yyyy HH:mm:ss.fff',[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::AssumeLocal);$ev=@{};foreach($line in ($chunk -split "`r?`n")){if(!$line.Contains("`t")){continue};$f=$line -split "`t";$nm=$f[0].Trim();if($names -contains $nm){$v=[Collections.Generic.List[double]]::new();for($j=1;$j-lt$f.Count;$j++){$v.Add((Num $f[$j]))};$ev[$nm]=$v.ToArray()}};if(@($names|?{!$ev.ContainsKey($_)}).Count){continue};$t=($inter+$slope*[double]$dt.ToFileTimeUtc())/$qpf;$dur=$ev['CPU_CLK_UNHALTED.REF_TSC'][1]/2112002720.0;if($dur -gt 0){$records.Add([pscustomobject]@{s=$t-$dur;e=$t;d=$dur;ev=$ev})}}
 $use=@($records|?{$_.s -lt $b -and $_.e -gt $a -and $_.s-.001 -ge $pa -and $_.e+.001 -le $pb});for($core=0;$core-lt 8;$core++){$num=0.;$den=0.;$wn=0.;$wd=0.;$sn=0.;$sd=0.;$inst=0.;$cyc=0.;$ref=0.;foreach($r in $use){foreach($lp in @([int](2*$core),[int](2*$core+1))){$i=$lp+1;$n=$r.ev['OFFCORE_REQUESTS.L3_MISS_DEMAND_DATA_RD'][$i];$d=$r.ev['OFFCORE_REQUESTS.DEMAND_DATA_RD'][$i];$num+=$n;$den+=$d;if($lp%2 -eq 0){$wn+=$n;$wd+=$d}else{$sn+=$n;$sd+=$d};$inst+=$r.ev['INST_RETIRED.ANY'][$i];$cyc+=$r.ev['CPU_CLK_UNHALTED.THREAD'][$i];$ref+=$r.ev['CPU_CLK_UNHALTED.REF_TSC'][$i]}};$result.Add([pscustomobject]@{capture=$cap;mode=$mode;Pcore=$core;LP_pair="$(2*$core),$(2*$core+1)";windows=$use.Count;block_s=[math]::Round($b-$a,6);L3_miss_num=$num;offcore_demand_den=$den;LLC_fraction=if($den){$num/$den}else{[double]::NaN};offcore_per_s=$den/($b-$a);worker_L3_miss_num=$wn;worker_offcore_demand_den=$wd;sibling_L3_miss_num=$sn;sibling_offcore_demand_den=$sd;INST_RETIRED=$inst;CPU_CLK_UNHALTED_THREAD=$cyc;CPU_CLK_UNHALTED_REF_TSC=$ref})}}
$out=Join-Path $root 'D8_CONTROL_COUNTS_r5.csv';$result|Export-Csv -NoTypeInformation -Encoding utf8 -LiteralPath $out;$result|Format-Table mode,Pcore,windows,L3_miss_num,offcore_demand_den,LLC_fraction,offcore_per_s -AutoSize|Out-String -Width 260|Write-Output
